import{r as s}from"./chunks/relatedArticles.DIHQAH-1.js";import{I as o,o as i,c as r,b6 as l,J as n,k as d}from"./chunks/framework.BUXTSoD9.js";const b=JSON.parse('{"title":"아이디어에서 AI 제품까지 - Easy-Vibe 학습 로드맵","description":"AI 프로그래밍을 배우기 위한 전체 로드맵: 제로 베이스에서 풀스택 개발까지. Vibe Coding, Claude Code, Cursor 같은 AI IDE 도구를 익히고, 제품 사고, 풀스택 개발, AI 기능 통합을 배웁니다.","frontmatter":{"title":"아이디어에서 AI 제품까지 - Easy-Vibe 학습 로드맵","description":"AI 프로그래밍을 배우기 위한 전체 로드맵: 제로 베이스에서 풀스택 개발까지. Vibe Coding, Claude Code, Cursor 같은 AI IDE 도구를 익히고, 제품 사고, 풀스택 개발, AI 기능 통합을 배웁니다."},"headers":[],"relativePath":"ko-kr/stage-1/learning-map/index.md","filePath":"ko-kr/stage-1/learning-map/index.md"}'),p={name:"ko-kr/stage-1/learning-map/index.md"},A=Object.assign(p,{setup(c){const a=s["ko-kr/stage-1/learning-map"]??[];return(u,t)=>{const e=o("RelatedArticlesSection");return i(),r("div",null,[t[0]||(t[0]=l('<h1 id="아이디어에서-ai-제품까지" tabindex="-1">아이디어에서 AI 제품까지 <a class="header-anchor" href="#아이디어에서-ai-제품까지" aria-label="Permalink to “아이디어에서 AI 제품까지”">​</a></h1><div class="info custom-block"><p class="custom-block-title">특별 감사</p><p><strong>칭화대학교 선전 국제대학원</strong> 학생 여러분의 본 과정 테스트, 피드백, 지원에 특별히 감사드립니다! 여러분의 의견과 기여가 이 과정을 더 나은 곳으로 만들었습니다. <a href="https://github.com/datawhalechina/easy-vibe#-contributing--contributors" target="_blank" rel="noreferrer">👉 전체 기여자 목록 보기</a></p></div><p>예전에는 소프트웨어를 만드는 진입 장벽이 매우 높았습니다: 프로그래밍을 알아야 하고, 알고리즘을 이해해야 하며, 몇 년의 프로젝트 경험도 필요했습니다. 지금은 다릅니다. 아이디어만 있으면 AI가 코드를 작성해 줍니다.</p><p>이것은 거대한 변화입니다: <strong>프로그래밍 언어가 자연어로 변하고 있습니다.</strong></p><p>대형 언어 모델(LLM)의 등장으로, 개발은 더 이상 &quot;기술 고수의 전유물&quot;이 아니라 모든 사람이 사용할 수 있는 도구가 되었습니다. 예전에 가장 어려웠던 것은 &quot;코드를 어떻게 쓸까&quot;였고, 지금 가장 어려운 것은 &quot;<strong>무엇을 만들까</strong>&quot;입니다.</p><blockquote><p><strong>Vibe Coding이란?</strong> 간단히 말해, &quot;말로 프로그래밍하는 것&quot;입니다. Vibe Coding은 코드를 직접 작성하는 대신, AI와 대화하는 것만으로 프로그래밍 프로젝트를 완수하는 방식을 의미합니다.</p></blockquote><p>물론, AI가 코드를 작성하는 것은 첫 번째 단계일 뿐입니다. 정말로 사용 가능한 제품을 만들려면, 다음과 같은 문제도 만나게 됩니다:</p><ul><li>AI가 어떻게 깔끔하고 유지보수 가능한 코드를 작성하게 할 것인가?</li><li>산발적인 코드를 어떻게 실행 가능한 애플리케이션으로 조립할 것인가?</li><li>애플리케이션을 어떻게 실제로 온라인에 공개하고, 사람들이 사용하게 할 것인가?</li><li>텍스트 생성, 이미지 인식 같은 AI 능력을 어떻게 제품에 넣을 것인가?</li></ul><p>이런 질문에 대한 답을 이 과정에서 찾을 수 있습니다.</p><p>학생이든, 교사든, 의사든, 노동자든, 기술을 전혀 모르는 일반인이든 상관없습니다 -- 몇 년 동안 프로그래밍을 먼저 배울 필요 없이, 2주면 실행 가능하고 시연할 수 있는 제품 프로토타입을 만들 수 있습니다.</p><table tabindex="0"><thead><tr><th>당신의 신분</th><th>이 과정이 도와줄 수 있는 것</th></tr></thead><tbody><tr><td>학생</td><td>과제, 대회, 창업, 직접 프로젝트를 만들어 더 이상 다른 사람에게 부탁하지 않음</td></tr><tr><td>직장인</td><td>반복 업무를 자동화하고, 효율을 높이며, 부업까지 개발</td></tr><tr><td>제품 관리자 / 디자이너</td><td>아이디어가 더 이상 종이 위에만 머물지 않고, 빠르게 Demo를 만들어 상사/고객에게 보여줌</td></tr><tr><td>창업자 / 중소기업주</td><td>저비용으로 아이디어를 검증하고, 수만 원을 들여 외주를 맡기지 않고도 MVP를 만듦</td></tr><tr><td>교사 / 교육 종사자</td><td>교육 도구, 강의 자료, 자동 출제를 만들어 교육 효율을 높임</td></tr><tr><td>의사 / 변호사 / 전문 직업인</td><td>전문 프로세스를 자동화하고, 자신만의 효율 도구를 구축</td></tr><tr><td>누구나</td><td>AI로 생활/업무의 구체적인 문제를 해결하고, 불가능을 가능하게 만듦</td></tr></tbody></table><p>AI 시대에는 실행력과 아이디어가 항상 기술보다 더 중요합니다.</p><h2 id="성장-경로-ai를-사용할-줄-아는-것-에서-ai-제품을-만들-줄-아는-것-까지" tabindex="-1">성장 경로: &quot;AI를 사용할 줄 아는 것&quot;에서 &quot;AI 제품을 만들 줄 아는 것&quot;까지 <a class="header-anchor" href="#성장-경로-ai를-사용할-줄-아는-것-에서-ai-제품을-만들-줄-아는-것-까지" aria-label="Permalink to “성장 경로: &quot;AI를 사용할 줄 아는 것&quot;에서 &quot;AI 제품을 만들 줄 아는 것&quot;까지”">​</a></h2><div class="stage-intro"><div class="stage-card"><div class="stage-icon">🎮</div><h3>초보자 입문</h3><p class="stage-role">AI 프로그래밍 체험</p><div class="stage-tags"><span>스네이크 미니 게임</span><span>제로 베이스 시작</span><span>Vibecoding 첫 체험</span><span>몇 분 만에 생성</span></div></div></div><div class="stage-grid"><div class="stage-card"><div class="stage-icon">🛠️</div><h3>1단계</h3><p class="stage-role">제품 관리자 / 운영</p><div class="stage-tags"><span>AI IDE (Cursor/Claude)</span><span>요구사항 분해 &amp; 프로토타입</span><span>AI 능력 연동</span><span>완전한 Demo 개발</span></div></div><div class="stage-card"><div class="stage-icon">💻</div><h3>2단계</h3><p class="stage-role">초중급 개발 / 인디 개발자</p><div class="stage-tags"><span>Figma에서 코드로</span><span>Supabase 데이터베이스</span><span>Stripe 결제 연동</span><span>Dify 지식 베이스</span></div></div><div class="stage-card"><div class="stage-icon">🚀</div><h3>3단계</h3><p class="stage-role">고급 개발 / 아키텍트</p><div class="stage-tags"><span>Web/미니프로그램/멀티플랫폼</span><span>MCP 고급 도구</span><span>RAG &amp; LangGraph</span><span>고급 엔지니어 사고</span></div></div></div><p>이 완전한 학습 경로를 통해, 다음을 얻게 됩니다:</p><ul><li><strong>Vibe Coding 개발 능력:</strong> vibecoding 사고와 AI 코딩 도구를 능숙하게 사용하여, 개발 효율을 몇 배로 높입니다. 더 이상 문법을 외울 필요 없이, AI가 고품질 코드를 생성하도록 안내하는 방법을 배웁니다.</li><li><strong>풀스택 개발 기술:</strong> UI 설계에서 프론트엔드 구현, 데이터베이스 설계에서 API 개발, 로컬 개발에서 클라우드 배포까지, 현대 웹 애플리케이션의 완전한 기술 스택을 마스터합니다.</li><li><strong>AI 능력 통합:</strong> 다양한 멀티모달 AI API를 호출하는 방법을 배우고, 텍스트, 이미지, 음성 등 AI 능력을 애플리케이션에 원활하게 통합하며, RAG 등의 기술을 통해 지능형 제품을 구축합니다.</li><li><strong>제품 사고와 운영 능력:</strong> 사용자 조사에서 요구사항 분해, MVP 설계에서 제품 반복, 결제 연동에서 사용자 관리까지, 완전한 제품 개발과 운영 루프를 형성합니다.</li></ul><h1 id="배우고-나면-무엇을-할-수-있을까" tabindex="-1">배우고 나면 무엇을 할 수 있을까? <a class="header-anchor" href="#배우고-나면-무엇을-할-수-있을까" aria-label="Permalink to “배우고 나면 무엇을 할 수 있을까?”">​</a></h1><h2 id="_1단계-첫-번째-제품-프로토타입-만들기" tabindex="-1">1단계: 첫 번째 제품 프로토타입 만들기 <a class="header-anchor" href="#_1단계-첫-번째-제품-프로토타입-만들기" aria-label="Permalink to “1단계: 첫 번째 제품 프로토타입 만들기”">​</a></h2><p>이 단계는 프로그래밍 기반이 전혀 없거나, 조금은 알지만 자신감이 부족한 분들에게 적합합니다. 많은 이론 지식을 먼저 배울 필요 없이, 바로 따라 하면서 AI 도구로 코드를 작성하는 법을 배웁니다.</p><p><strong>배우고 나면 할 수 있는 것:</strong></p><ul><li>AI 프로그래밍 도구로 독립적으로 웹 애플리케이션 하나를 완성</li><li>제품 아이디어를 클릭 가능하고 상호작용 가능한 프로토타입으로 만들기</li><li>프로토타입에 AI 기능 추가(예: 텍스트에서 이미지 생성, 스마트 대화)</li><li>오류를 만났을 때 어떻게 파악하고 해결하는지 알기</li></ul><p>간단히 말해, &quot;실행 가능하고, 남에게 시연할 수 있는&quot; 것을 만들 수 있게 됩니다.</p><p>먼저 미니 게임을 통해 AI 프로그래밍을 체험하고, AI 프로그래밍 도구로 코드를 작성하고 오류를 수정하는 법을 배울 수 있습니다. 그다음 간단한 페이지부터 시작해 점차 상호작용이 가능한 다중 페이지 애플리케이션을 만들고, 텍스트에서 이미지 생성, 스마트 대화 같은 AI 기능을 추가합니다. 마지막으로 완전한 프로젝트를 독립적으로 완성하여, 여러분의 크리에이티비티가 실제로 실현될 가능성을 갖게 됩니다.</p><h1 id="왜-프로젝트-기반-훈련을-사용할까" tabindex="-1">왜 프로젝트 기반 훈련을 사용할까? <a class="header-anchor" href="#왜-프로젝트-기반-훈련을-사용할까" aria-label="Permalink to “왜 프로젝트 기반 훈련을 사용할까?”">​</a></h1><blockquote><p><strong>현실 세계의 도전</strong></p><p>이유는 사실 간단합니다: 대부분의 학생이 현재 상태로 직장에 바로 들어가면, 실제 프로젝트와 상사/고객의 &quot;사회적 수술&quot; 아래서 한 걸음도 나아가기 어려울 가능성이 높습니다. 현실 세계에서 더 흔한 시나리오는:</p></blockquote><blockquote><p>당신의 멘토/상사: 우리는 xxx를 만들어야 하고, 목표는 yyy 효과를 달성하는 것입니다.</p><p>문서? 기존 프레임워크? 상세한 요구사항 설명? 많은 경우 존재하지 않습니다.</p></blockquote><p>실제 업무의 많은 과제는 본질적으로 고도로 불확실한 환경에서 한 번도 본 적 없는 문제를 해결하는 것입니다: 요구사항은 모호하고, 경계는 변하며, 아무도 정답을 알려주지 않습니다. 스스로 자료를 찾고, 실험을 하고, 프로토타입을 만들고, 끊임없이 반복하여, 마지막에 &quot;실행 가능하고, 사용 가능하고, 온라인에 공개할 수 있는&quot; 솔루션을 제시해야 합니다.</p><p>이 과정이 하고 싶은 것은, 비교적 안전한 환경에서, 미리 한 번 &quot;모의 사회적 수술&quot;을 경험하게 하는 것입니다:</p><ul><li>겉보기에 약간 난이도가 있는 프로젝트 과제를 통해, 문제 분해, 솔루션 설계, 스스로 자료 찾기를 연습하게 함</li><li>그다지 &quot;쉬운&quot; 스캐폴딩과 코드를 통해, 중대형 코드베이스를 읽고, 이해하고, 수정하는 법을 배움</li><li>아이디어에서 온라인 공개까지의 완전한 루프를 통해, 실제 제품이 0에서 1이 되는 완전한 과정을 경험</li></ul><p>단기적으로, 이런 훈련은 확실히 꽤 고역입니다; 하지만 장기적으로, 취업과 직업 발전에서 경쟁력을 크게 높여줍니다: 더 많은 일을 감당하고, 불확실한 환경에서 돌파구를 더 잘 찾으며, AI를 실제로 구현되는 제품으로 만드는 능력도 더 갖게 되어, &quot;Demo만 가지고 놀기&quot; 단계에 머물지 않게 됩니다.</p><h1 id="질문의-기술-ai-시대의-필수-스킬" tabindex="-1">질문의 기술: AI 시대의 필수 스킬 <a class="header-anchor" href="#질문의-기술-ai-시대의-필수-스킬" aria-label="Permalink to “질문의 기술: AI 시대의 필수 스킬”">​</a></h1><p>AI 시대에는 질문하는 것도 하나의 &quot;기본기&quot;입니다. 같은 코드, 같은 오류에 대해, <strong>어떻게 질문하느냐가 AI가 어떤 답을 줄 수 있는지를 거의 결정합니다</strong>: 막연한 이야기인지, 아니면 단계별로 실행 가능한 수정 방법인지.</p><p><strong>좋은 습관 들이기</strong>: &quot;AI에게 질문하기&quot;를 일상 개발 프로세스의 일부로 만드세요: 모르거나 막힌 문제를 만나면 바로 물어보세요.</p><h2 id="왜-이것이-필수-스킬인가" tabindex="-1">왜 이것이 필수 스킬인가? <a class="header-anchor" href="#왜-이것이-필수-스킬인가" aria-label="Permalink to “왜 이것이 필수 스킬인가?”">​</a></h2><ul><li><strong>현실에는 거의 완전한 문서가 없음</strong>: 더 많은 경우, 직면하는 것은 불명확한 요구사항, 반쯤 완성된 코드, 산발적인 오류 정보</li><li><strong>AI는 당신의 휴대용 멘토 + 동료</strong>: 질문을 잘하는 사람은 그것을 &quot;고품질 짝 프로그래밍&quot;으로 만들 수 있음</li><li><strong>능력의 상한은 소통에 의해 결정됨</strong>: 핵심 정보를 더 많이 제공하고, 출력 형식을 더 잘 제약할수록, 답이 더 사용 가능해짐</li></ul><p><strong>흔한 오해</strong>: &quot;왜 오류가 나?&quot;라고 한마디만 물으면 보통 추측만 잔뜩 얻게 됩니다. 컨텍스트를 보완해야 실행 가능한 솔루션을 얻을 수 있습니다.</p><h2 id="ai에게-정보를-어떻게-먹이는가-스크린샷-vs-복사-붙여넣기" tabindex="-1">AI에게 정보를 어떻게 &quot;먹이는가&quot;: 스크린샷 vs 복사 붙여넣기 <a class="header-anchor" href="#ai에게-정보를-어떻게-먹이는가-스크린샷-vs-복사-붙여넣기" aria-label="Permalink to “AI에게 정보를 어떻게 &quot;먹이는가&quot;: 스크린샷 vs 복사 붙여넣기”">​</a></h2><p>두 방식 모두 가능하지만, 용도가 다릅니다:</p><table tabindex="0"><thead><tr><th>방식</th><th>적용 시나리오</th><th>핵심 요구사항</th></tr></thead><tbody><tr><td><strong>복사 붙여넣기</strong></td><td>오류 스택, 로그, 코드, 설정, API 반환</td><td>가능한 한 완전하게, 키워드 한 줄만 자르지 마세요</td></tr><tr><td><strong>스크린샷</strong></td><td>UI 레이아웃 문제, 인터랙션 이상, 도구 인터페이스에서 버튼을 찾을 수 없음</td><td>전체 화면 캡처 + 핵심 영역 표시, 글로 된 설명 한 문장을 함께 제공하는 것이 좋음</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">⚠️ 중요한 전제</p><p><strong>모든 AI가 이미지 입력을 지원하는 것은 아닙니다.</strong> 스크린샷으로 소통하려면 AI가 멀티모달 능력(즉, 이미지를 이해하고 분석할 수 있는 능력)을 갖추어야 합니다. 현재 이미지 입력을 지원하는 AI에는 Claude(Anthropic), GPT-4V/GPT-4o(OpenAI), Gemini(Google), 그리고 일부 국산 대형 모델인 퉁이치엔원, 원신이연 등이 있습니다.</p><p><strong>사용 중인 AI가 이미지 입력을 지원하지 않는다면</strong>, 스크린샷이 인식되지 않으므로, 이때는 복사 붙여넣기 텍스트 방식으로 소통하세요.</p></div><h2 id="ai가-잘-설명해-주도록-만드는-프롬프트-기술" tabindex="-1">AI가 &quot;잘 설명해 주도록&quot; 만드는 프롬프트 기술 <a class="header-anchor" href="#ai가-잘-설명해-주도록-만드는-프롬프트-기술" aria-label="Permalink to “AI가 &quot;잘 설명해 주도록&quot; 만드는 프롬프트 기술”">​</a></h2><p>답만 원하는 것이 아니라, 답을 &quot;배우고&quot; 싶다면. 다음과 비슷한 지시어를 사용하면 설명 품질을 크게 높일 수 있습니다:</p><blockquote><p><strong>학습형 질문 예시</strong></p><ul><li>&quot;먼저 5문장으로 이 개념을 명확히 설명한 다음, 몇 가지 질문을 통해 제가 제대로 이해했는지 확인해 주세요.&quot;</li><li>&quot;이 오류 메시지를 자세히 설명해 주세요. 왜 오류가 나는지 이해가 안 돼요.&quot;</li></ul></blockquote><h1 id="오래-참아도-안-풀려요-포기하고-싶어요" tabindex="-1">오래 참아도 안 풀려요, 포기하고 싶어요 <a class="header-anchor" href="#오래-참아도-안-풀려요-포기하고-싶어요" aria-label="Permalink to “오래 참아도 안 풀려요, 포기하고 싶어요”">​</a></h1><p>아마도 당신이 고집하는 방법이 맞지 않을 수 있습니다. 혼자 어둠 속에서 버티지 말고, 작가와 조교들과 이야기해 보세요: 이미 시도한 방법, 만난 구체적인 막힌 점, 그리고 현재 심리 상태를 솔직하게 말하세요. 많은 경우, 방향을 조금만 조정하고, 핵심 지식을 하나만 보완하면, 다시 앞으로 나아갈 수 있습니다.</p><h1 id="튜토리얼의-일부-설계가-불합리하다고-생각해요" tabindex="-1">튜토리얼의 일부 설계가 불합리하다고 생각해요 <a class="header-anchor" href="#튜토리얼의-일부-설계가-불합리하다고-생각해요" aria-label="Permalink to “튜토리얼의 일부 설계가 불합리하다고 생각해요”">​</a></h1><p>언제든지 작가에게 연락하거나, 이슈를 제출하거나, 그룹/수업에서 직접 피드백해 주세요. 우리는 여러분과 함께 이 튜토리얼을 점점 더 좋게 만들어 가고 싶습니다: 어디가 불명확한지, 어디서 경험이 좋지 않았는지, 어디서 헛되이 시간을 보냈는지, 모두 솔직하게 지적해 주세요. 더 진실하고, 더 구체적인 피드백일수록, 나중에 오시는 분들이 불필요하게 겪는 어려움을 줄이는 데 더 도움이 됩니다.</p><h1 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to “Reference”">​</a></h1><ul><li><a href="https://nju-projectn.github.io/ics-pa-gitbook/ics2025/" target="_blank" rel="noreferrer">난징대학교 컴퓨터과학기술학과 컴퓨터시스템기초 과정 실험</a></li></ul>',50)),n(e,{title:"다음에 무엇을 배울 수 있을까",description:"AI를 사용할 줄 아는 것에서 제품을 만들 줄 아는 것까지의 경로를 따라 계속 나아가세요.",items:d(a)},null,8,["items"])])}}});export{b as __pageData,A as default};
